function [xhist, Pfull, errENU, nisHist] = appendix_solver_core( ...
    cfg, sat, vis, trk, meas, recTrue, R_e2n, R_n2e, r0_guess)
%APPENDIX_SOLVER_CORE Core WP5230 EKF loop excerpt.
%
% This listing is a compact report version of the estimator core in
% functions/solver/real_strtg_sequential_EKF_fastrealistic.m. It assumes
% that satellite states, visibility, tracking selection, and measurements
% have already been generated by the surrounding simulation code.

[K, Nsat] = size(vis);

nx = 5;
iDE = 1; iDN = 2; iDU = 3;
iCB = 4; iCD = 5;

% State: [dE dN dU clockBias clockDrift]^T.
x = zeros(nx,1);
x(iCB) = cfg.clk.filter_init_bias_mps;
x(iCD) = cfg.clk.filter_init_drift_mps2;

P = diag([ ...
    cfg.init.sigENU_m(1)^2, ...
    cfg.init.sigENU_m(2)^2, ...
    cfg.init.sigENU_m(3)^2, ...
    cfg.P0_clkBias, ...
    cfg.P0_clkDrift]);

A = eye(nx);
A(iCB,iCD) = cfg.dt;

qPos = cfg.sigma_pos_rw^2;
Q = diag([ ...
    qPos * cfg.dt, ...
    qPos * cfg.dt, ...
    qPos * cfg.dt, ...
    cfg.clk.filt.sigmaBias_rw_mps_sqrt^2 * cfg.dt, ...
    cfg.clk.filt.sigmaDrift_rw_mps2_sqrt^2 * cfg.dt]);

Inx = eye(nx);

xhist    = nan(nx,K);
Pfull    = cell(K,1);
errENU   = nan(3,K);
nisHist  = nan(K,1);

consecutive_tracking = zeros(1,Nsat);

for k = 1:K
    % Prediction.
    x = A * x;
    P = A * P * A' + Q;

    % Select usable satellites at this epoch.
    avail = false(1,Nsat);
    if cfg.meas.useDoppler
        avail = avail | ~isnan(meas.dopp.obs(k,:));
    end
    if cfg.meas.useDopplerRate
        avail = avail | ~isnan(meas.rate.obs(k,:));
    end

    if strcmpi(cfg.capture.mode,'allVisible')
        useList = find(vis(k,:) & avail);
        if ~isempty(useList)
            [~,ord] = sort(sat.elev(k,useList), 'descend');
            useList = useList(ord);
        end
    else
        sSel = trk.sid(k);
        if trk.blackout(k) || sSel == 0 || ~vis(k,sSel) || ~avail(sSel)
            useList = [];
        else
            useList = sSel;
        end
    end

    for ss = 1:Nsat
        if ~ismember(ss,useList) || (~isempty(trk) && trk.blackout(k))
            consecutive_tracking(ss) = 0;
        end
    end

    epochNIS = [];

    for s = useList
        ps = sat.pos(:,1,s,k);
        vs = sat.vel(:,1,s,k);
        as = sat.acc(:,1,s,k);

        hasD  = cfg.meas.useDoppler     && ~isnan(meas.dopp.obs(k,s));
        hasDd = cfg.meas.useDopplerRate && ~isnan(meas.rate.obs(k,s));

        consecutive_tracking(s) = consecutive_tracking(s) + 1;

        if hasD && hasDd
            z = [meas.dopp.obs(k,s); meas.rate.obs(k,s)];
            Rk = diag([meas.dopp.sigma(k,s)^2, ...
                       meas.rate.sigma(k,s)^2]);

            if consecutive_tracking(s) <= cfg.filter.startupInflateEpochs
                Rk = cfg.filter.startupRmult * Rk;
            end

            [x, P, accepted, nis] = appendix_vector_iekf_update( ...
                x, P, z, Rk, ...
                @(xi) appendix_doppler_rate_measurement_model( ...
                    xi, r0_guess + R_n2e*xi(iDE:iDU), R_n2e, ...
                    ps, vs, as, k, s, cfg, meas, iCB, iCD, nx), ...
                cfg, Inx, [iDE iDN iDU]);

            if accepted
                epochNIS(end+1,1) = nis; %#ok<AGROW>
            end

        elseif hasD
            z  = meas.dopp.obs(k,s);
            Rk = meas.dopp.sigma(k,s)^2;

            if consecutive_tracking(s) <= cfg.filter.startupInflateEpochs
                Rk = cfg.filter.startupRmult * Rk;
            end

            [x, P, accepted, nis] = scalar_iekf_update( ...
                x, P, z, Rk, ...
                @(xi) meas_model_doppler( ...
                    xi, r0_guess + R_n2e*xi(iDE:iDU), R_n2e, ...
                    ps, vs, k, s, cfg, meas, iCB, nx), ...
                cfg, Inx, [iDE iDN iDU]);

            if accepted
                epochNIS(end+1,1) = nis; %#ok<AGROW>
            end
        end
    end

    % Height pseudo-measurement.
    if cfg.height.enable
        [x, P] = scalar_iekf_update( ...
            x, P, cfg.height.z0_m, cfg.height.sigma_m^2, ...
            @(xi) meas_model_height_constraint(xi, iDU, nx), ...
            cfg, Inx, [iDE iDN iDU]);
    end

    if ~isempty(epochNIS)
        nisHist(k) = mean(epochNIS);
    end

    xhist(:,k) = x;
    Pfull{k} = P;

    rEst = r0_guess + R_n2e * x(iDE:iDU);
    errENU(:,k) = R_e2n * (rEst - recTrue);
end
end
